mapper.update:
update emp
username = #{username}, password = #{password}, name = #{name}, gender = #{gender}, phone = #{phone}, job = #{job}, salary = #{salary}, image = #{image}, entry_date = #{entryDate}, dept_id = #{deptId}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select e.id, e.username, e.name, e.gender,e.image,e.job, e.salary ,e.entry_date, e.dept_id, d.name deptName,e.create_time, e.update_time from emp e left join dept d on e.dept_id = d.id
and e.name like concat('%',#{name},'%')
and e.gender = #{gender}
and e.entry_date between #{begin} and #{end}
order by e.update_time desc
